const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>x!==0&&Math.abs(x)<1e-5?x.toExponential(3).replace('.',','):Number(x.toFixed(5)).toLocaleString('ru-RU',{maximumFractionDigits:5});
export function normaliseYearTwo(raw={}){const s={a:1,n:5,mode:'bounded',a0:1,domain:'compact',R:3,time:.5};for(const [key,min,max,step] of [['a',-2,2,.25],['n',1,40,1],['a0',.25,2,.25],['R',0,20,.5],['time',.1,2,.1]])if(typeof raw?.[key]==='number'&&Number.isFinite(raw[key]))s[key]=Math.round(Math.max(min,Math.min(max,raw[key]))/step)*step;if(raw?.mode==='spike')s.mode='spike';if(raw?.domain==='open')s.domain='open';return s;}
export const tailBound=(a0,R)=>Math.exp(-a0*R)/a0;
export const heat=(x,t)=>Math.exp(-x*x/(4*t))/Math.sqrt(4*Math.PI*t);
const slider=(key,label,min,max,step,value)=>'<label class="model-control">'+label+' <output data-year-value="'+key+'">'+fmt(value)+'</output><input aria-label="'+label+'" data-year-field="'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'"></label>';
const select=(key,label,values,value)=>'<label>'+label+'<select data-year-field="'+key+'">'+values.map(([v,l])=>'<option value="'+v+'" '+(v===value?'selected':'')+'>'+l+'</option>').join('')+'</select></label>';
const svg=(body,label)=>'<svg viewBox="0 0 400 220" role="img" aria-label="'+esc(label)+'"><path d="M35 180H375M45 190V25" fill="none" stroke="#829488"/>'+body+'</svg>';
export function yearTwoOutput(id,s){
 if(id==='higher')return svg('<rect x="'+Math.min(200,200+70*s.a)+'" y="70" width="'+Math.max(1,Math.abs(70*s.a))+'" height="80" fill="#c9dacd" stroke="#174c43"/><text x="65" y="205">F(x,y)=(a x,y); a='+fmt(s.a)+'</text>','Образ единичного квадрата при линейном отображении')+'<div class="lab-conclusion"><strong>det DF = '+fmt(s.a)+'</strong><p>'+(s.a===0?'В этом линейном примере квадрат сжимается в отрезок, отображение не инъективно.':'В этом линейном примере F обратимо: F⁻¹(u,v)=(u/a,v). Знак a задаёт ориентацию; площадь меняется в |a| раз.')+' Для произвольного нелинейного F нулевой якобиан сам по себе не исключает непрерывную обратимость.</p></div>';
 if(id==='lebesgue'){const amplitude=s.mode==='spike'?s.n:1,integral=amplitude/s.n;return svg('<path d="M45 180V55H'+(45+300/s.n)+'V180" fill="#c9dacd" stroke="#174c43" stroke-width="2"/><text x="55" y="40">высота '+fmt(amplitude)+'</text><text x="50" y="205">0</text><text x="325" y="205">1</text><text x="120" y="160">ширина 1/n</text>','Ступень высоты '+amplitude+' на интервале (0,1/'+s.n+'); вертикальный масштаб подстраивается под высоту')+'<p class="caption">Вертикальный масштаб подстраивается; численная высота подписана. Горизонтальная ось x∈[0,1].</p><div class="lab-conclusion"><strong>n='+s.n+'; ∫fₙ='+fmt(integral)+'</strong><p>'+(s.mode==='spike'?'fₙ=n1_(0,1/n)→0 в каждой точке (0,1), но интеграл постоянно равен 1. Общей интегрируемой мажоранты нет.':'fₙ=1_(0,1/n)→0 в каждой точке (0,1), а интеграл 1/n→0. Общая мажоранта 1 интегрируема; теорема Лебега применима.')+'</p></div>';}
 if(id==='uniformintegrals')return '<div class="formula">∫ᴿ∞ e⁻ᵃˣdx=e⁻ᵃᴿ/a; R='+fmt(s.R)+'</div><div class="lab-conclusion"><strong>'+(s.domain==='open'?'a∈(0,2]: sup хвоста = +∞':'a∈['+fmt(s.a0)+',2]: sup хвоста = '+fmt(tailBound(s.a0,s.R)))+'</strong><p>'+(s.domain==='open'?'При любом фиксированном R выражение неограниченно при a→0. Каждый отдельный интеграл сходится, но сходимость на этом множестве параметров неравномерна.':'Общая положительная нижняя граница a₀ даёт оценку e⁻ᵃ⁰ᴿ/a₀→0. Это равномерная сходимость на выбранном компактном интервале параметров.')+'</p></div>';
 if(id==='fourier'){const path=Array.from({length:121},(_,i)=>{const x=-3+i/20;return(i?'L':'M')+(45+(x+3)*50).toFixed(2)+' '+(180-heat(x,s.time)*155).toFixed(2);}).join(' ');return svg('<path d="'+path+'" fill="none" stroke="#174c43" stroke-width="2"/><text x="40" y="205">−3</text><text x="190" y="205">0</text><text x="340" y="205">3</text>','График теплового ядра на [-3,3], t='+fmt(s.time))+'<div class="lab-conclusion"><strong>t='+fmt(s.time)+'; G_t(0)='+fmt(heat(0,s.time))+'</strong><p>Показана только часть графика x∈[−3,3]; интеграл по всей ℝ равен 1. С ростом t максимум уменьшается, а ширина возрастает. Преобразование ядра равно e⁻ᵗξ², оно удовлетворяет ∂ₜG=∂ₓₓG.</p></div>';}
 return '';
}
export function yearTwoLab(c,s){let controls='';if(c.id==='higher')controls=slider('a','Коэффициент a',-2,2,.25,s.a);if(c.id==='lebesgue')controls=select('mode','Последовательность',[['bounded','1_(0,1/n)'],['spike','n1_(0,1/n)']],s.mode)+slider('n','Номер n',1,40,1,s.n);if(c.id==='uniformintegrals')controls=select('domain','Множество параметров',[['compact','[a₀,2]'],['open','(0,2]']],s.domain)+slider('a0','Нижняя граница a₀',.25,2,.25,s.a0)+slider('R','Начало хвоста R',0,20,.5,s.R);if(c.id==='fourier')controls=slider('time','Время t',.1,2,.1,s.time);return (controls?'<h2>Проверка условий</h2><section class="lab-panel advanced-model"><div class="lab-controls">'+controls+'</div><div id="year-two-output" aria-live="polite">'+yearTwoOutput(c.id,s)+'</div></section>':'')+'<h2 class="section-space">Разобранные задачи</h2>'+c.workedExamples.map(e=>'<details class="deep worked-example" open><summary>'+esc(e.title)+'</summary><p>'+esc(e.statement)+'</p><ol>'+e.steps.map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol><div class="formula">'+esc(e.result)+'</div></details>').join('');}
